#!/bin/bash
set -euo pipefail
umask 077
P=/scratch/jjyeung/orch_n30/lever7/nfa/fix2/t/psim/P
test -e "$P/PACKAGE.json"
test ! -e "$P/a/70.txt"
q=$(squeue -u jjyeung -h -o '%j' | grep '^a15_cot_apc8b836b4ae536' || true)
test -z "$q"
/scratch/jjyeung/envs/p1cpu/bin/python -I -s -B - "$P" <<'PY'
import base64,gzip,hashlib,json,os,sys
from pathlib import Path
p=Path(sys.argv[1]);spec=json.loads('{"PACKAGE.json": {"mode": 384, "new": "d10f8a7222ff342c2ec47aac357d3b49215baa76a8cf8ec62f83f9371cf23c1f", "old": "b7a04c51cd5c3db16b8fa71cf2c51f38d8fc6b1a5c42f0f92f9bc7eb2efafe01"}, "a/5.py": {"mode": 384, "new": "a29c0bc4bf40b0f1aefa7e1fb947cb6323f30d450c7391aeb7f607b5ac77f49a", "old": "fb641d57efbc49307b7d943273ed1647b5fea9b0454610d7d6e0d6722c387770"}}');h=lambda f:hashlib.sha256(f.read_bytes()).hexdigest()
order=['a/5.py', 'PACKAGE.json']
blobs={'a/5.py':base64.b64decode(''),'PACKAGE.json':base64.b64decode('')}
for n in order:
    if h(p/n)!=spec[n]['old']:raise SystemExit('E81 '+n+' is not the placed pre-fix file')
    if os.path.lexists(str(p/n)+'.pre2'):raise SystemExit('E82 '+n+'.pre2 exists')
if os.path.lexists(str(p/'2.json')+'.pre2'):raise SystemExit('E82 2.json.pre2 exists')
for n in order:
    data=gzip.decompress(blobs[n])
    if hashlib.sha256(data).hexdigest()!=spec[n]['new']:raise SystemExit('E83 '+n)
    os.rename(p/n,str(p/n)+'.pre2')
    fd=os.open(p/n,os.O_WRONLY|os.O_CREAT|os.O_EXCL,spec[n]['mode'])
    with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
    got=h(p/n)
    if got!=spec[n]['new'] or h(Path(str(p/n)+'.pre2'))!=spec[n]['old']:raise SystemExit('E84 '+n)
    print(n,got,'kept',n+'.pre2',spec[n]['old'])
if (p/'2.json').exists():
    os.rename(p/'2.json',str(p/'2.json')+'.pre2');print('2.json moved to 2.json.pre2; run o_check.sh next')
pins=json.loads((p/'PACKAGE.json').read_text())['files']
bad=[n for n,v in pins.items() if h(p/n)!=v]
if bad:raise SystemExit('E85 pins differ: '+' '.join(bad))
print('pins ok',len(pins))
PY
